    @Test
    public void getNameReturnsTagName() {
        // Arrange
        String tagName = "test";
        when(Tag.valueOf(tagName).getName()).thenReturn(tagName);

        // Act
        String result = Tag.valueOf(tagName).getName();

        // Assert
        assertThat(result, is(tagName));
    }

